'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;let state;const compare=new Set();const key='rxr-object-studio-v1';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){toast('Browser storage unavailable. Export your review to save it.')}}
function tab(name){if(!['trajectories','models','placements'].includes(name))name='trajectories';$$('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$$('.tab-panel').forEach(p=>p.hidden=p.id!==name);history.replaceState(null,'','#'+name)}
function stats(){const ids=new Set(state.routes);$('#stats').innerHTML=`<div class="stat"><strong>${ids.size}</strong><span>selected trajectories</span></div><div class="stat"><strong>${new Set(data.routes.filter(r=>ids.has(r.id)).map(r=>r.scene)).size}</strong><span>selected Matterport scenes</span></div><div class="stat"><strong>${data.models.length}</strong><span>curated model options</span></div><div class="stat"><strong>${data.research.new_downloads}</strong><span>new scan files downloaded</span></div>`}
function routeFilters(){let rows=data.routes.filter(r=>{const scope=$('#route-scope').value;const selected=state.routes.includes(r.id);const split=$('#route-split').value;const query=$('#route-search').value.toLowerCase();return (scope==='all'||(scope==='selected'?selected:!selected))&&(split==='all'||split===r.split)&&`${r.id} ${r.scene} ${r.path_id} ${r.description}`.toLowerCase().includes(query)});if($('#route-sort').value==='length')rows.sort((a,b)=>b.length_m-a.length_m);return rows}
function renderRoutes(){const rows=routeFilters();$('#route-result').textContent=`${rows.length} routes shown · original guide lengths · ${state.routes.length} in your selection`;
$('#route-grid').innerHTML=rows.map(r=>`<article class="route-card"><div class="route-images">${r.images.map((im,i)=>`<img loading="lazy" src="${esc(im)}" alt="Route ${r.id}, goal heading ${i*90} degrees">`).join('')}<span class="route-tag">ENV ${String(r.id).padStart(2,'0')} · ${esc(r.split)}</span></div><div class="card-content"><div class="card-top"><span class="badge ${r.id===4?'amber':state.routes.includes(r.id)?'green':''}">${r.id===4?'Placement in review':state.routes.includes(r.id)?'Selected by you':'Reviewed endpoint'}</span><span class="route-length">${r.length_m.toFixed(2)} <small>m</small></span></div><div class="card-title">${esc(r.scene)} <span style="font-weight:400;color:var(--muted)">/ ${r.path_id}</span></div><div class="route-description">${esc(r.description)}</div><div class="card-foot"><label class="check-label"><input type="checkbox" data-route-select="${r.id}" ${state.routes.includes(r.id)?'checked':''}> Keep route</label><button class="text-button" data-route-open="${r.id}">Inspect trajectory ↗</button></div></div></article>`).join('')||'<div class="empty">No routes match these filters.</div>';stats()}
function openDialog(title,html){$('#detail-label').textContent=title;$('#detail-body').className='detail-body';$('#detail-body').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0}
function routeMap(r,step=0){const points=r.points_mp3d;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);let loX=Math.min(...xs),loY=Math.min(...ys),w=Math.max(...xs)-loX,h=Math.max(...ys)-loY;const scale=Math.min(480/Math.max(w,1),320/Math.max(h,1));const project=p=>[35+(p[0]-loX)*scale,35+(loY+h-p[1])*scale];let path=points.map(p=>project(p).join(',')).join(' ');return `<svg class="map" viewBox="0 0 550 390" role="img" aria-label="Original route viewpoint graph in Matterport horizontal coordinates"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M 30 0 L 0 0 0 30" fill="none" stroke="#dce4d9" stroke-width="1"/></pattern></defs><rect width="550" height="390" fill="url(#grid)"/><polyline points="${path}" fill="none" stroke="#48715c" stroke-width="3.5" stroke-linejoin="round"/>${points.map((p,i)=>{const [x,y]=project(p);return `<circle cx="${x}" cy="${y}" r="${i===0||i===points.length-1?7:3}" fill="${i===0?'#278659':i===points.length-1?'#cf603c':'#91ac95'}" stroke="#f7faf5" stroke-width="1.5"><title>Viewpoint ${i+1}: height ${p[2].toFixed(2)} m</title></circle>`}).join('')}<circle id="map-cursor" cx="${project(points[step])[0]}" cy="${project(points[step])[1]}" r="10" fill="none" stroke="#c65a2e" stroke-width="3"/></svg>`}
function openRoute(id){const r=data.routes.find(r=>r.id===id);let heading=0;const note=state.notes['route-'+id]||'';openDialog(`ENV ${String(id).padStart(2,'0')} / RxR ${r.split} / path ${r.path_id}`,`<div class="detail-layout"><div><img class="detail-hero" id="route-image" src="${r.images[0]}" alt="Goal view, heading 0 degrees"><div class="heading-buttons">${[0,90,180,270].map((h,i)=>`<button data-heading="${i}" class="${i===0?'active':''}">${h}°</button>`).join('')}</div><div class="map-caption">Original goal viewpoint. These are four directions from the same camera position.</div><div id="route-map">${routeMap(r)}</div><div class="map-caption">Viewpoint graph, MP3D X–Y projection · green start / orange goal · floor changes can overlap.</div><div class="range-row"><label for="route-step">Viewpoint</label><input type="range" id="route-step" min="0" max="${r.viewpoints.length-1}" value="0"><span id="step-label">1 / ${r.viewpoints.length}</span></div><div class="map-caption" id="step-id">${esc(r.viewpoints[0])} · height ${r.points_mp3d[0][2].toFixed(2)} m</div></div><div><span class="badge green">${state.routes.includes(r.id)?'In your selection':'Outside your selection'}</span><h3 class="detail-heading">${esc(r.scene)}</h3><p>${esc(r.description)}</p><div class="facts"><div class="fact">Original guide route<strong>${r.length_m.toFixed(2)} m</strong></div><div class="fact">Guide viewpoints<strong>${r.viewpoints.length}</strong></div><div class="fact">Start–goal straight line<strong>${r.direct_distance_m.toFixed(2)} m</strong></div><div class="fact">Dataset split<strong>${esc(r.split)}</strong></div></div><div class="detail-note">The guide length is not a shortest-path distance. Goal furniture is a proposed location for an authored school-bag task.</div><label class="field-label" for="instruction-select">Original RxR guide instruction</label><select id="instruction-select">${r.instructions.map((v,i)=>`<option value="${i}">${esc(v.language)} · instruction ${v.instruction_id}</option>`).join('')}</select><div class="instruction" id="instruction-text">${esc(r.instructions[0].instruction)}</div><label class="field-label" for="route-note">Your placement notes</label><textarea id="route-note" rows="4" placeholder="Choose furniture, note preferred heading or placement…">${esc(note)}</textarea><div class="detail-note">Goal viewpoint: ${esc(r.goal_viewpoint)}</div>${id===4?'<button class="source-link" id="go-placements" style="border:0">View both bag placements ↗</button>':''}</div></div>`);
$$('[data-heading]').forEach(b=>b.onclick=()=>{heading=+b.dataset.heading;$('#route-image').src=r.images[heading];$('#route-image').alt=`Goal heading ${heading*90} degrees`;$$('[data-heading]').forEach(x=>x.classList.toggle('active',x===b))});$('#route-step').oninput=e=>{const i=+e.target.value;$('#route-map').innerHTML=routeMap(r,i);$('#step-label').textContent=`${i+1} / ${r.viewpoints.length}`;$('#step-id').textContent=`${r.viewpoints[i]} · height ${r.points_mp3d[i][2].toFixed(2)} m`};$('#instruction-select').onchange=e=>$('#instruction-text').textContent=r.instructions[+e.target.value].instruction;$('#route-note').oninput=e=>{state.notes['route-'+id]=e.target.value;save()};if($('#go-placements'))$('#go-placements').onclick=()=>{$('#detail').close();tab('placements')};}
function modelRows(){const q=$('#model-search').value.toLowerCase(),mode=$('#model-access').value;return data.models.filter(m=>`${m.name} ${m.author} ${m.platform} ${m.fit} ${m.note} ${m.texture}`.toLowerCase().includes(q)&&(mode==='all'||(mode==='local'&&m.downloaded)||(mode==='paid'&&m.access==='Paid')||(mode==='free'&&['Login required','Downloaded','Free checkout'].includes(m.access))||(mode==='reference'&&m.access.includes('Reference'))||(mode==='saved'&&state.models.includes(m.id))))}
function modelBadge(m){return m.downloaded?'green':m.access==='Paid'?'amber':m.access.includes('Reference')?'':'blue'}
function modelImage(m,cls='model-image'){return m.preview?`<img class="${cls}" loading="lazy" src="${esc(m.preview)}" alt="${esc(m.name)} — public source preview">`:`<div class="model-placeholder"><strong>3D</strong><span>${esc(m.platform)}</span><span>Preview on official source ↗</span></div>`}
function renderModels(){const rows=modelRows();$('#model-result').textContent=`${rows.length} curated options shown · ${data.research.screened_model_records} public model records screened · ${state.models.length} shortlisted`;
$('#model-grid').innerHTML=rows.map(m=>`<article class="model-card">${modelImage(m)}<div class="card-content"><div class="pill-row"><span class="badge ${modelBadge(m)}">${esc(m.access)}</span>${m.preferred?'<span class="badge green">Start here</span>':''}</div><div class="card-title">${esc(m.name)}</div><div class="model-author">${esc(m.author)} · ${esc(m.platform)}</div><div class="model-info">${esc(m.texture)}<br>${esc(m.price)}</div><div class="model-note">${esc(m.fit)}</div><div class="model-actions"><button class="text-button" data-model-open="${m.id}">Inspect model ↗</button><label class="check-label"><input data-model-select="${m.id}" type="checkbox" ${state.models.includes(m.id)?'checked':''} aria-label="Shortlist ${esc(m.name)}"> Save</label></div><label class="check-label" style="margin-top:8px"><input type="checkbox" data-compare="${m.id}" ${compare.has(m.id)?'checked':''}> Compare</label></div></article>`).join('')||'<div class="empty">No models match these filters.</div>';renderCompare()}
function renderCompare(){const tray=$('#compare-tray');tray.hidden=!compare.size;tray.className='compare-tray';tray.innerHTML=`<span>${compare.size} / 3 selected to compare</span><div><button id="compare-clear">Clear</button> <button id="compare-open">Compare models ↗</button></div>`;$('#compare-clear').onclick=()=>{compare.clear();renderModels()};$('#compare-open').onclick=()=>{const ms=data.models.filter(m=>compare.has(m.id));openDialog('Compare model choices',`<div class="compare-grid" style="--compare-columns:${ms.length}">${ms.map(m=>`<div>${modelImage(m)}<h3>${esc(m.name)}</h3><span class="badge ${modelBadge(m)}">${esc(m.access)}</span><p><strong>${esc(m.texture)}</strong><br>${esc(m.formats)}<br>${esc(m.license)}</p><p>${esc(m.note)}</p><a class="source-link" href="${esc(m.source)}" target="_blank" rel="noopener noreferrer">Official source ↗</a></div>`).join('')}</div>`)}}
function loadViewer(){if($('#viewer-module'))return;const s=document.createElement('script');s.type='module';s.id='viewer-module';s.src='assets/model-viewer.min.js';document.head.appendChild(s)}
function openModel(id){const m=data.models.find(m=>m.id===id);openDialog(`${m.platform} / model review`, `<div class="detail-layout"><div><div id="model-stage">${modelImage(m,'detail-hero')}</div><div class="model-view-buttons">${m.local_file?'<button id="local-view">Inspect local 3D file</button>':''}${m.embed?'<button id="author-view">Open author’s 3D viewer</button>':''}</div><div class="map-caption" id="model-stage-caption">Public author / seller preview. It is not a Habitat render.</div></div><div><span class="badge ${modelBadge(m)}">${esc(m.access)}</span><h3 class="detail-heading">${esc(m.name)}</h3><p>${esc(m.author)} · ${esc(m.fit)}</p><div class="facts"><div class="fact">Texture evidence<strong style="font-size:13px">${esc(m.texture)}</strong></div><div class="fact">Access / listed price<strong style="font-size:13px">${esc(m.price)}</strong></div></div><div class="license">${esc(m.license)}${m.license_url?` · <a href="${esc(m.license_url)}" target="_blank" rel="noopener noreferrer">License</a>`:''}</div><p class="detail-note">${esc(m.note)}</p><p class="detail-note"><strong>Formats:</strong> ${esc(m.formats)}${m.triangles?`<br><strong>Source triangle count:</strong> ${m.triangles.toLocaleString()}`:''}</p>${m.mesh_inspection?`<div class="instruction"><strong>Actual downloaded GLB inspection</strong><br>${m.mesh_inspection.meshes} meshes · ${m.mesh_inspection.faces.toLocaleString()} triangles<br>Embedded base-color maps: ${esc(m.texture)}<br>${(m.mesh_inspection.bytes/1048576).toFixed(1)} MB<br><small>SHA-256 ${esc(m.mesh_inspection.source_sha256)}</small></div>`:''}<a class="source-link" href="${esc(m.source)}" target="_blank" rel="noopener noreferrer">Official source ↗</a>${m.local_file?`<a class="source-link outline-link" href="${esc(m.local_file)}" download>Download local GLB ↓</a>`:''}<label class="check-label"><input id="model-detail-save" type="checkbox" ${state.models.includes(m.id)?'checked':''}> Keep in my model shortlist</label><label class="field-label" for="model-note" style="margin-top:18px">Your model review</label><textarea id="model-note" rows="3" placeholder="Shape, fabric, realism, school-bag suitability…">${esc(state.notes['model-'+id]||'')}</textarea></div></div>`);
$('#model-detail-save').onchange=e=>{state.models=e.target.checked?[...new Set([...state.models,id])]:state.models.filter(v=>v!==id);save();renderModels()};$('#model-note').oninput=e=>{state.notes['model-'+id]=e.target.value;save()};if($('#local-view'))$('#local-view').onclick=()=>{loadViewer();$('#model-stage-caption').textContent='Actual downloaded GLB · drag to rotate · scroll to zoom. This is a model inspection, not a Habitat render.';$('#model-stage').innerHTML=`<div class="viewer"><model-viewer src="${esc(m.local_file)}" camera-controls auto-rotate shadow-intensity=".8" exposure="1" interaction-prompt="none" alt="Actual local 3D mesh of ${esc(m.name)}"><div slot="poster" class="viewer-fallback">Loading the local mesh…<br>Drag to rotate · scroll to zoom</div></model-viewer></div>`};if($('#author-view'))$('#author-view').onclick=()=>{$('#model-stage-caption').textContent='Live author viewer from Sketchfab · download status is separate from viewing access.';$('#model-stage').innerHTML=`<iframe class="viewer" title="Author’s interactive viewer: ${esc(m.name)}" src="${esc(m.embed)}" allow="fullscreen; xr-spatial-tracking" allowfullscreen></iframe>`};
}
function renderPlacements(){$('#placement-grid').innerHTML=data.placements.map(p=>`<article class="placement-card"><img id="placement-image-${p.id}" src="${p.images.contact}" alt="${esc(p.label)} bag contact view"><div class="card-content"><div class="card-top"><h3 class="card-title">${esc(p.label)}</h3><span class="badge amber">Candidate</span></div><div class="thumbnails">${Object.entries(p.images).map(([kind,img])=>`<button data-placement-kind="${kind}" data-placement="${p.id}" class="${kind==='contact'?'active':''}" aria-label="${esc(p.label)} ${kind} view"><img src="${img}" alt="${kind} view"></button>`).join('')}</div><div class="measurements"><div>Upper bag lean<strong>${p.lean_degrees.toFixed(1)}°</strong></div><div>Measured base rim clearance<strong>${(p.contact.base_gap_min_max_m[0]*1000).toFixed(1)}–${(p.contact.base_gap_min_max_m[1]*1000).toFixed(1)} mm</strong></div></div><p class="detail-note">Support X / Y / Z: ${p.position.map(v=>v.toFixed(3)).join(' / ')} m</p><label class="field-label" for="placement-status-${p.id}">Your visual assessment</label><select id="placement-status-${p.id}" data-placement-status="${p.id}"><option value="pending">Review pending</option><option value="acceptable">Looks acceptable</option><option value="adjust">Needs placement adjustment</option><option value="model">Needs a different bag model</option></select></div></article>`).join('');data.placements.forEach(p=>{$(`#placement-status-${p.id}`).value=state.placements[p.id]||'pending'});$('#placement-notes').value=state.notes.placement||''}
function exportReview(){const review={exported_at:new Date().toISOString(),original_user_selected_indices:data.selected_indices,selected_trajectories:data.routes.filter(r=>state.routes.includes(r.id)).map(r=>({review_index:r.id,scene:r.scene,path_id:r.path_id,split:r.split,original_guide_length_m:r.length_m,goal_viewpoint:r.goal_viewpoint,notes:state.notes['route-'+r.id]||''})),selected_models:data.models.filter(m=>state.models.includes(m.id)).map(m=>({id:m.id,name:m.name,source:m.source,access:m.access,local_file:m.local_file,notes:state.notes['model-'+m.id]||''})),placement_assessments:state.placements,placement_notes:state.notes.placement||'',limitations:data.limitations};const blob=new Blob([JSON.stringify(review,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rxr-schoolbag-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Review exported as JSON')}
async function init(){try{const res=await fetch('data.json');if(!res.ok)throw new Error('Data not available');data=await res.json();let old;try{old=JSON.parse(localStorage.getItem(key))}catch(e){}state={routes:data.selected_indices,models:[],placements:{},notes:{},...old};state.routes=state.routes.filter(id=>data.routes.some(r=>r.id===id));$('#model-total').textContent=data.models.length;$('#updated').textContent='Data checked 15 Oct 2026';renderRoutes();renderModels();renderPlacements();tab(location.hash.slice(1));$('#close-detail').onclick=()=>{$('#detail').close();$('#detail-body').innerHTML=''};$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#close-detail').click()});$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));['route-search','route-scope','route-split','route-sort'].forEach(id=>$('#'+id).addEventListener(id.endsWith('search')?'input':'change',renderRoutes));['model-search','model-access'].forEach(id=>$('#'+id).addEventListener(id.endsWith('search')?'input':'change',renderModels));$('#export').onclick=exportReview;$('#placement-notes').oninput=e=>{state.notes.placement=e.target.value;save()};document.addEventListener('click',e=>{const r=e.target.closest('[data-route-open]'),m=e.target.closest('[data-model-open]'),p=e.target.closest('[data-placement-kind]');if(r)openRoute(+r.dataset.routeOpen);if(m)openModel(m.dataset.modelOpen);if(p){const placement=data.placements.find(v=>v.id===p.dataset.placement);$('#placement-image-'+placement.id).src=placement.images[p.dataset.placementKind];p.closest('.thumbnails').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===p))}});document.addEventListener('change',e=>{const t=e.target;if(t.dataset.routeSelect){const id=+t.dataset.routeSelect;state.routes=t.checked?[...new Set([...state.routes,id])].sort((a,b)=>a-b):state.routes.filter(v=>v!==id);save();renderRoutes()}if(t.dataset.modelSelect){const id=t.dataset.modelSelect;state.models=t.checked?[...new Set([...state.models,id])]:state.models.filter(v=>v!==id);save();renderModels()}if(t.dataset.compare){const id=t.dataset.compare;if(t.checked&&compare.size>=3){t.checked=false;toast('Compare up to three models at a time');return}if(t.checked)compare.add(id);else compare.delete(id);renderCompare()}if(t.dataset.placementStatus){state.placements[t.dataset.placementStatus]=t.value;save()}});window.dashboardReady=true;}catch(e){$('#route-grid').innerHTML='<div class="empty">Unable to load dashboard data. Start the local server and open its HTTP address.</div>';console.error(e)}}init();
